CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar, "role" varchar not null default 'customer', "phone" varchar, "doc_number" varchar, "passport_number" varchar, "birth_date" date, "notes" text, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "permissions" text);
