CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "personal_access_tokens" ("id" integer primary key autoincrement not null, "tokenable_type" varchar not null, "tokenable_id" integer not null, "name" text not null, "token" varchar not null, "abilities" text, "last_used_at" datetime, "expires_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "suppliers" ("id" integer primary key autoincrement not null, "name" varchar not null, "contact_name" varchar, "email" varchar, "phone" varchar, "website" varchar, "service_type" varchar not null, "location" varchar, "cuit" varchar, "bank_name" varchar, "cbu" varchar, "alias" varchar, "account_number" varchar, "created_at" datetime, "updated_at" datetime, "category" varchar);
CREATE TABLE IF NOT EXISTS "supplier_accounts" ("id" integer primary key autoincrement not null, "supplier_id" integer not null, "bank_name" varchar not null, "account_number" varchar, "cbu" varchar, "alias" varchar, "currency" varchar not null default 'ARS', "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("supplier_id") references "suppliers"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "financial_accounts" ("id" integer primary key autoincrement not null, "name" varchar not null, "currency" varchar not null default 'ARS', "balance" numeric not null default '0', "cbu" varchar, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "transaction_categories" ("id" integer primary key autoincrement not null, "name" varchar not null, "type" varchar not null, "is_system" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "transactions" ("id" integer primary key autoincrement not null, "booking_id" integer, "supplier_id" integer, "supplier_account_id" integer, "payer_name" varchar, "type" varchar not null, "amount" numeric not null, "currency" varchar not null, "exchange_rate" numeric, "amount_usd_fixed" numeric, "date" date, "method" varchar not null, "notes" text, "reference" varchar, "created_at" datetime, "updated_at" datetime, "financial_account_id" integer, "transaction_category_id" integer, "attachment_path" varchar, "payable_type" varchar, "payable_id" integer, "tax_details" text, foreign key("transaction_category_id") references transaction_categories("id") on delete set null on update no action, foreign key("financial_account_id") references financial_accounts("id") on delete set null on update no action, foreign key("booking_id") references bookings("id") on delete set null on update no action, foreign key("supplier_id") references suppliers("id") on delete set null on update no action, foreign key("supplier_account_id") references supplier_accounts("id") on delete set null on update no action);
CREATE TABLE IF NOT EXISTS "customers" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar, "phone" varchar, "document_number" varchar, "passport_number" varchar, "birth_date" date, "address" text, "history_json" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "messages" ("id" integer primary key autoincrement not null, "lead_id" integer not null, "role" varchar not null, "content" text not null, "created_at" datetime, "updated_at" datetime, foreign key("lead_id") references "leads"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "quotations" ("id" integer primary key autoincrement not null, "quotation_number" varchar not null, "customer_id" integer, "lead_id" integer, "destination" varchar not null, "travel_date" date, "nights" integer, "passengers" integer not null default '1', "items" text, "total_cost" numeric not null default '0', "total_sell" numeric not null default '0', "profit" numeric not null default '0', "currency" varchar not null default 'USD', "status" varchar not null default 'draft', "valid_until" date, "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("customer_id") references "customers"("id") on delete set null, foreign key("lead_id") references "leads"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "leads" ("id" integer primary key autoincrement not null, "customer_id" integer, "source" varchar not null, "temperature" varchar not null, "status" varchar not null, "customer_name" varchar not null, "customer_phone" varchar not null, "raw_message" text not null, "ai_data" text, "ai_summary" text, "needs_human_attention" tinyint(1) not null default ('0'), "created_at" datetime, "updated_at" datetime, foreign key("customer_id") references "customers"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "bookings" ("id" integer primary key autoincrement not null, "lead_id" integer, "customer_id" integer, "file_number" varchar not null, "holder_name" varchar not null, "travel_date" date not null, "total_cost" numeric not null default ('0'), "total_sell" numeric not null default ('0'), "profit" numeric not null default ('0'), "status" varchar not null default ('presupuesto'), "created_at" datetime, "updated_at" datetime, "currency" varchar not null default ('USD'), "exchange_rate" numeric not null default ('1'), "internal_notes" text, foreign key("lead_id") references leads("id") on delete set null on update no action, foreign key("customer_id") references "customers"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "booking_items" ("id" integer primary key autoincrement not null, "booking_id" integer not null, "supplier_id" integer, "service_type" varchar not null, "description" varchar not null, "cost" numeric not null, "sell" numeric not null, "created_at" datetime, "updated_at" datetime, "currency" varchar not null default ('USD'), "exchange_rate" numeric not null default ('1'), foreign key("supplier_id") references suppliers("id") on delete restrict on update no action, foreign key("booking_id") references bookings("id") on delete cascade on update no action);
